insert into research_item (jurisdiction_code, item, status, detail, where_to_get, checked_on) values ('AT', 'structure', 'have', 'One national regime: income tax, the 27.5% tax on capital income, the 30% tax on real estate gains and the real property acquisition tax are federal and the same in all nine states. There is no wealth, inheritance or gift tax. Only the municipal real estate tax (Grundsteuer) varies by municipality, and it is not counted. Klagenfurt am Wörthersee (capital of Carinthia) sets no rate of its own: it is not a separate region.', null, '2026-11-02') on conflict (jurisdiction_code, item) do update set status = excluded.status, detail = excluded.detail, where_to_get = excluded.where_to_get, checked_on = excluded.checked_on;
