insert into research_item (jurisdiction_code, item, status, detail, where_to_get, checked_on) values ('AT', 'wealth:millionaires', 'blocked', 'Austria is not in the UBS Global Wealth Report 2026 Millionaire Index table (p.21 lists 34 markets; Austria appears only in the wealth-per-adult rankings: mean 279,989, median 71,378 US$).', 'UBS Global Wealth Databook 2026 (the companion to the Global Wealth Report, https://www.ubs.com/global/en/wealthmanagement/insights/global-wealth-report.html), table of adults by wealth band, row Austria, column USD 1m+ → save in PDFs/ and tell Claude.', '2026-11-02') on conflict (jurisdiction_code, item) do update set status = excluded.status, detail = excluded.detail, where_to_get = excluded.where_to_get, checked_on = excluded.checked_on;
