insert into research_item (jurisdiction_code, item, status, detail, where_to_get, checked_on) values ('AT', 'wealth:trusts_count', 'blocked', 'Austrian law has no domestic trust; trusts and similar arrangements are registered in the beneficial-owners register (WiEReG, run by the Ministry of Finance), which publishes no count of them that we found. The private foundation (Privatstiftung) is a different legal form and is not counted as a trust.', 'Ask the Register Authority at the Austrian Ministry of Finance (WiEReG, https://www.bmf.gv.at/themen/finanzmarkt/wirtschaftliche-eigentuemer.html) for the number of trusts and trust-like arrangements registered; save the answer in PDFs/ and tell Claude.', '2026-11-02') on conflict (jurisdiction_code, item) do update set status = excluded.status, detail = excluded.detail, where_to_get = excluded.where_to_get, checked_on = excluded.checked_on;
